<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { listarInterrupciones, obtenerInterrupcion, restablecerInterrupcion, type InterrupcionOperacional } from '../services/interrupciones'
const records=ref<InterrupcionOperacional[]>([]),selected=ref<InterrupcionOperacional|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),modal=ref(false),restoreId=ref<number|null>(null),totals=reactive({activas:0,restablecidas:0,programadas:0,difundidas:0}),filters=reactive({criterio:'',fecha_inicio:'',fecha_fin:'',estado:''}),restore=reactive({fecha_restablecimiento:'',observacion:''})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarInterrupciones({...filters,page:target});records.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(totals,r.totales)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',fecha_inicio:'',fecha_fin:'',estado:''});load(1)}
async function detail(item:InterrupcionOperacional){loading.value=true;try{selected.value=await obtenerInterrupcion(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
function openRestore(item:InterrupcionOperacional){restoreId.value=item.id;restore.fecha_restablecimiento='';restore.observacion='';modal.value=true}
async function submitRestore(){if(!restoreId.value||!restore.fecha_restablecimiento||!restore.observacion.trim()){error.value='Ingrese la fecha de restablecimiento y la observación.';return}if(!confirm('¿Restablecer el servicio? La interrupción se marcará como atendida.'))return;saving.value=true;error.value='';try{await restablecerInterrupcion(restoreId.value,{...restore,observacion:restore.observacion.trim()});modal.value=false;selected.value=null;success.value='Servicio restablecido correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Sistemas y componentes / Interrupciones</nav><header class="hero"><div class="mark">IN</div><div><small>DANA · CONTINUIDAD DEL SERVICIO</small><h1>Interrupciones</h1><p>Consulta afectaciones, difusión, programación y restablecimiento.</p></div><button>Ver dashboard</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article class="danger"><small>SIN RESTABLECER</small><b>{{totals.activas}}</b></article><article><small>RESTABLECIDAS</small><b>{{totals.restablecidas}}</b></article><article><small>CON PROGRAMACIÓN</small><b>{{totals.programadas}}</b></article><article><small>CON DIFUSIÓN</small><b>{{totals.difundidas}}</b></article></section><form class="filters" @submit.prevent="load(1)"><label>Descripción<input v-model.trim="filters.criterio" placeholder="Descripción de la interrupción"></label><label>Interrupción desde<input v-model="filters.fecha_inicio" type="date"></label><label>Interrupción hasta<input v-model="filters.fecha_fin" type="date"></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option value="1">Restablecidas</option><option value="0">Sin restablecer</option></select></label><div><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><div v-if="loading" class="empty">Cargando interrupciones…</div><div v-else-if="!records.length" class="empty">No se encontraron interrupciones.</div><section v-else class="cards"><article v-for="item in records" :key="item.id" :class="{restored:item.restablecido}"><header><div class="drop">{{item.restablecido?'●':'×'}}</div><div><small>INTERRUPCIÓN #{{item.id}}</small><h2>{{item.fecha_inicio}} · {{item.hora_inicio}}</h2></div><span>{{item.restablecido?'RESTABLECIDO':'SIN RESTABLECER'}}</span></header><p>{{item.detalle_motivo}}</p><dl><div><dt>Tipo</dt><dd>{{item.tipo}}</dd></div><div><dt>Motivo</dt><dd>{{item.motivo}}</dd></div><div><dt>Servicio afectado</dt><dd>{{item.servicio}}</dd></div><div><dt>Conexiones / UU</dt><dd>{{item.conexiones_afectadas}} / {{item.uu_afectadas}}</dd></div></dl><div class="badges"><b :class="{ok:item.con_programacion}">{{item.con_programacion?'CON PROGRAMACIÓN':'SIN PROGRAMAR'}}</b><b :class="{ok:item.con_difusion}">{{item.con_difusion?'CON DIFUSIÓN':'SIN DIFUSIÓN'}}</b></div><footer><button class="detail" @click="detail(item)">Detallar</button><button v-if="!item.restablecido" class="restore" @click="openRestore(item)">Restablecer servicio</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>{{total}} registros · Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="selected" class="drawer-backdrop" @mousedown.self="selected=null"><aside class="drawer"><header><div><small>FICHA OPERACIONAL</small><h2>Interrupción #{{selected.id}}</h2></div><button @click="selected=null">×</button></header><div class="status" :class="{ok:selected.restablecido}">{{selected.restablecido?'SERVICIO RESTABLECIDO':'INTERRUPCIÓN ACTIVA'}}</div><section><h3>Información de la afectación</h3><p>{{selected.detalle_motivo}}</p><dl><div><dt>Inicio</dt><dd>{{selected.fecha_inicio}} {{selected.hora_inicio}}</dd></div><div><dt>Tipo</dt><dd>{{selected.tipo}}</dd></div><div><dt>Servicio</dt><dd>{{selected.servicio}}</dd></div><div><dt>Motivo</dt><dd>{{selected.motivo}}</dd></div><div><dt>Áreas</dt><dd>{{selected.areas_afectadas.join(', ')||'Ninguna'}}</dd></div><div><dt>Archivos</dt><dd>{{selected.archivos_count}}</dd></div></dl></section><section><h3>Tareas relacionadas</h3><article v-for="task in selected.tareas" :key="task.id"><b>{{task.tipo}}</b><span>{{task.estado}}</span></article><p v-if="!selected.tareas.length">Sin tareas relacionadas.</p></section><section v-if="selected.restablecido"><h3>Restablecimiento</h3><b>{{selected.fecha_restablecimiento}}</b><p>{{selected.observacion_restablecimiento}}</p></section><button v-else class="drawer-restore" @click="openRestore(selected)">Restablecer el servicio</button></aside></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="submitRestore"><header><div><small>CONTINUIDAD OPERACIONAL</small><h2>Restablecer interrupción #{{restoreId}}</h2></div><button type="button" @click="modal=false">×</button></header><p>Registre la fecha efectiva y una observación del restablecimiento.</p><label>Fecha y hora de restablecimiento *<input v-model="restore.fecha_restablecimiento" type="datetime-local" required></label><label>Observación *<textarea v-model="restore.observacion" rows="4" placeholder="Detalle las condiciones del restablecimiento" required></textarea></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Procesando…':'Guardar y restablecer'}}</button></footer></form></div></div></template>
